"""Local, read-only-source report for the completed representation pilot."""
from pathlib import Path
import json,html,shutil
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
ROOT=Path(__file__).resolve().parents[1];RUN=ROOT/'runs/office200_representation_20260928';OUT=RUN/'review';SITE=ROOT.parent/'paltering-research-site/dist'
def read(p):return json.loads(Path(p).read_text())
def save(p,x):Path(p).write_text(json.dumps(x,ensure_ascii=False,indent=2)+'\n')
LABEL={'honest':'Honest','paltering':'Paltering','false_assertion':'Lie'}
NAMES={'whole_reply':'Original reply embedding','question_reply':'Question + reply embedding','evidence_relation':'Question, reply + evidence','contrastive':'Learned representation','context_only':'Question + evidence only','topic_model_length':'Topic, model + length only','permuted_labels':'Shuffled training labels'}
assert read(RUN/'completion.json')['status']=='completed';OUT.mkdir(exist_ok=True)
r=read(RUN/'results.json');rows=read(RUN/'predictions.json');maps=read(RUN/'maps.json');neighbors=read(RUN/'neighbors.json');metrics=r['metrics'];protocol=r['protocol'];e=html.escape
old=read(SITE/'office200/embeddings_data.json');oldrows={x['episode']:x for x in old['rows']}
for row in rows:assert oldrows[row['episode']]['reply']==row['reply'] and oldrows[row['episode']]['question']==row['question']
assert len(rows)==757
# New published payload: numerical analysis + IDs only. Existing published text is reused.
public_rows=[{k:v for k,v in row.items() if k not in ['reply','question','title']} for row in rows]
newdata={'rows':public_rows,'maps':maps,'neighbors':neighbors,'labels':LABEL}
save(OUT/'representation_data.json',newdata)
(OUT/'representation_data.js').write_text('window.REPRESENTATION='+json.dumps(newdata,ensure_ascii=False).replace('</','<\\/')+';\n')
save(OUT/'representation_summary.json',r);shutil.copy2(RUN/'protocol.json',OUT/'representation_protocol.json')
plt.rcParams.update({'font.family':'sans-serif','font.size':11,'axes.spines.top':False,'axes.spines.right':False,'svg.fonttype':'none'})
methods=list(NAMES);fig,ax=plt.subplots(figsize=(9.5,5.2),layout='constrained')
for i,k in enumerate(methods):
 m=metrics[k];val=m['macro_f1'];lo,hi=m['macro_f1_ci95'];ax.barh(i,val,color='#31536e' if k=='contrastive' else '#a8aca9',height=.58);ax.errorbar(val,i,xerr=[[max(0,val-lo)],[max(0,hi-val)]],fmt='none',ecolor='#242a2f',capsize=3);ax.text(hi+.012,i,f'{val:.3f}',va='center',fontsize=10)
ax.set_yticks(range(len(methods)),[NAMES[k] for k in methods]);ax.invert_yaxis();ax.set_xlim(0,1);ax.set_xlabel('Macro F1 · equal weight to Honest, Paltering and Lie');ax.grid(axis='x',alpha=.15);ax.set_axisbelow(True)
for ext in ['png','svg']:fig.savefig(OUT/f'representation_performance.{ext}',dpi=180)
plt.close(fig)
points=[p for p in maps if p['fold']==0];fig,ax=plt.subplots(figsize=(8.5,5.7),layout='constrained');colors={'honest':'#397563','paltering':'#9b6a13','false_assertion':'#66518f'}
for lab in LABEL:
 pts=[p for p in points if p['label']==lab];ax.scatter([p['x'] for p in pts],[p['y'] for p in pts],s=27,alpha=.75,color=colors[lab],label=f'{LABEL[lab]} · {len(pts)}')
ax.set_xlabel('PC1 of learned representation');ax.set_ylabel('PC2 of learned representation');ax.legend(frameon=False,loc='upper center',bbox_to_anchor=(.5,1.12),ncol=3);ax.set_title('Held-out replies · fold 1',loc='left',fontsize=12,pad=35)
for ext in ['png','svg']:fig.savefig(OUT/f'representation_map.{ext}',dpi=180)
plt.close(fig)
base=metrics['whole_reply']['macro_f1'];learn=metrics['contrastive']['macro_f1'];delta=r['paired_macro_f1_difference'];lo,hi=delta['ci95']
headline='The learned representation improves label prediction in this pilot.' if lo>0 else 'The learned representation performs worse than the original baseline.' if hi<0 else 'The learned representation does not show a clear improvement over the baseline.'
comparison=f'Macro F1 changed from {base:.3f} to {learn:.3f}. The paired difference is {delta["estimate"]:+.3f}, with a 95% family-bootstrap interval of {lo:+.3f} to {hi:+.3f}.'
trs=''
for k in methods:
 m=metrics[k];p=m['per_class']['paltering'];trs+=f'<tr class="{"featured" if k=="contrastive" else ""}"><th scope="row">{e(NAMES[k])}</th><td>{m["macro_f1"]:.3f}</td><td>{p["precision"]:.1%}</td><td>{p["recall"]:.1%}</td><td>{p["f1"]:.3f}</td></tr>'
stress=''.join(f'<tr><th scope="row">{e(NAMES[k])}</th><td>{v["macro_f1"]:.3f}</td><td>{v["per_class"]["paltering"]["precision"]:.1%}</td><td>{v["per_class"]["paltering"]["recall"]:.1%}</td></tr>' for k,v in r['family_and_model_heldout'].items())
retr=''.join(f'<tr><th scope="row">{name.title()}</th>'+''.join(f'<td>{v["top1_same_label_by_class"][lab]:.1%}</td>' for lab in LABEL)+f'<td>{v["macro_top1_same_label"]:.1%}</td></tr>' for name,v in r['retrieval'].items())
ex=''.join(f'<li><code>{e(x["episode"])}</code> — {e(x["reason"])}</li>' for x in protocol['excluded'])
conf=''
for k in ['whole_reply','contrastive']:
 matrix=metrics[k]['confusion_matrix'];body=''.join('<tr><th scope="row">'+LABEL[lab]+'</th>'+''.join(f'<td>{n}</td>' for n in matrix[i])+'</tr>' for i,lab in enumerate(LABEL));conf+=f'<h3>{e(NAMES[k])}</h3><table><thead><tr><th>Saved label ↓ / prediction →</th><th>Honest</th><th>Paltering</th><th>Lie</th></tr></thead><tbody>{body}</tbody></table>'
page=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Learning a representation · Office200</title><link rel="stylesheet" href="representation_base.css"><link rel="stylesheet" href="representation.css"></head><body><a class="skip" href="#results">Skip to results</a><nav class="top"><a href="https://true-words-paltering.a1178089646.chatgpt.site/">← Main article</a><div><a href="https://true-words-paltering.a1178089646.chatgpt.site/office200/embeddings">Embeddings</a><a href="https://true-words-paltering.a1178089646.chatgpt.site/office200/matched">Matched replies</a></div></nav><main><header class="prose intro"><p class="eyebrow">Representation pilot · 28 September 2026</p><h1>Learning from the replies</h1><p class="lead">{headline}</p><p>{comparison}</p><p>It does retrieve more similarly labeled paltering replies across topics and models: <strong>23 of 70 queries (32.9%)</strong>, compared with 10 of 70 (14.3%) using the original embedding. This is a possible aid for finding examples, not a validated detector of rhetorical tactics.</p><p class="small">757 replies · 189 scenarios · 50 families · 650 Honest / 70 Paltering / 37 Lie. Seven flagged labels were excluded. Labels are Qwen and Kimi’s saved agreement, not independent human validation. “Lie” means false assertion, not established intent. Additional API cost: <strong>$0</strong>.</p><p class="links"><a href="#results">Prediction results</a><a href="#map">Held-out map</a><a href="#cases">Inspect replies</a><a href="#method">Method</a></p></header><section class="wide" id="results"><h2>Does it predict labels on new scenario families?</h2><img class="figure" src="representation_performance.svg" alt="Macro F1 comparison for seven prespecified methods, with family-bootstrap intervals."><p class="caption">Macro F1 averages the three class F1 scores, giving each class equal weight. A score of 1 means perfect label prediction. Error bars resample scenario families from fixed held-out predictions; they do not include label or training-seed uncertainty.</p><div class="table-scroll"><table><thead><tr><th>Input / method</th><th>Macro F1</th><th>Paltering precision</th><th>Paltering recall</th><th>Paltering F1</th></tr></thead><tbody>{trs}</tbody></table></div><p class="small">Precision: of replies predicted as paltering, how many have that saved label? Recall: of the 70 saved paltering examples, how many were found? These are classification results, not paltering prevalence or reader effects.</p><details><summary>Confusion matrices</summary>{conf}</details><details><summary>Stricter check: unseen scenario families and unseen replying model</summary><p>Thirty train/test fits. For each test reply, its scenario family and all replies from its subject model are absent from training. These numbers use the same fixed settings.</p><div class="table-scroll"><table><thead><tr><th>Method</th><th>Macro F1</th><th>Paltering precision</th><th>Paltering recall</th></tr></thead><tbody>{stress}</tbody></table></div></details></section><section class="wide" id="map"><h2>Where do held-out replies land?</h2><p class="small">Each map contains only one fold’s test replies. The 16-dimensional representation and this two-dimensional display were fitted on that fold’s training data. Maps from different folds have different coordinate systems; do not compare their axes. Position is not an honesty score.</p><div class="controls"><label>Test fold <select id="fold">{''.join(f'<option value="{f}">Fold {f+1}</option>' for f in range(5))}</select></label><div class="legend">{''.join(f'<span><i style="background:{colors[k]}"></i>{v}</span>' for k,v in LABEL.items())}</div></div><svg id="scatter" viewBox="0 0 1000 560" role="group" aria-label="Held-out reply map; select a point to inspect its reply"></svg><p id="map-note" class="small" aria-live="polite"></p></section><section class="wide" id="cases"><h2>Inspect a prediction</h2><p>Every eligible reply is available, including mistakes. All predictions shown are from held-out evaluation. Source replies and evidence reuse the existing published embedding data.</p><div class="controls"><label>Saved label <select id="label"><option value="">All</option>{''.join(f'<option value="{k}">{v}</option>' for k,v in LABEL.items())}</select></label><label>Learned prediction <select id="match"><option value="">All</option><option value="correct">Agrees with saved label</option><option value="wrong">Disagrees with saved label</option><option value="gained">Baseline wrong, learned correct</option><option value="lost">Baseline correct, learned wrong</option></select></label><label class="grow">Reply <select id="reply-select"></select></label></div><p id="case-count" class="small" aria-live="polite"></p><div id="case-detail"></div></section><section class="wide"><h2>Do similar labels transfer across topics?</h2><p>Each held-out reply retrieves its nearest training reply from a different topic and a different subject model. We count whether their saved labels match. A matching outcome does not establish the same rhetorical tactic.</p><table><thead><tr><th>Representation</th><th>Honest queries</th><th>Paltering queries</th><th>Lie queries</th><th>Equal-class average</th></tr></thead><tbody>{retr}</tbody></table><p class="small">The viewer compares original and learned neighbors. Tactic-level transfer still needs independent annotation; no token receives an automatic honesty or deception label.</p></section><section class="prose" id="method"><h2>What was trained</h2><p>The original embedding model stays fixed. A training-only 64-dimensional PCA compresses the cached reply, question–reply and full incident-evidence vectors. Their coordinates, differences and elementwise products form the input. A linear projection learns a normalized <strong>16-dimensional representation</strong>; a class-balanced logistic classifier predicts the three labels.</p><p>Contrastive training brings together examples with the same label from different scenarios, with additional weight across topics. Differently labeled answers to the same scenario receive additional separation pressure. All pairs are constructed inside the training fold. Training uses 220 fixed steps; there was no search for settings that made these test results look better.</p><p>Neither judge’s explanation, authored honest reference, model name, nor researcher answer is a predictor input. Topic and scenario metadata organize training pairs but are not embedded features. The topic/model/length row is a separate confounding control.</p><p>The five family folds are retained from the prior embedding analysis. Previously reserved cases have already been analyzed, so this is exploratory cross-validation, <strong>not a pristine confirmatory test</strong>. A trained map can separate its training labels by construction; the held-out results are the evidence to assess.</p><p>Evidence is one aggregate vector per scenario, including public and internal records. It does not capture which records the subject actually retrieved. Vector differences do not implement logical entailment or fully model implication. The system learns provisional coding decisions; it does not establish speaker intention or recipient belief change.</p><details><summary>The seven excluded labels</summary><p>Original study labels remain unchanged. These seven are excluded here pending reconsideration; the rest have not received independent human validation.</p><ul>{ex}</ul></details><p class="links"><a href="representation_summary.json" download>Results and methods</a><a href="representation_protocol.json" download>Frozen protocol</a><a href="representation_data.json" download>Held-out predictions</a><a href="representation_performance.png">Performance figure</a><a href="representation_map.png">Fold 1 map</a></p></section></main><footer class="prose"><p>Offline analysis of the existing Office200 study. Original outputs, labels and embeddings are unchanged.</p></footer><script src="embeddings_data.js"></script><script src="representation_data.js"></script><script src="representation.js"></script></body></html>'''
(OUT/'index.html').write_text(page)
shutil.copy2(SITE/'mechanisms.css',OUT/'representation_base.css');shutil.copy2(SITE/'office200/embeddings_data.js',OUT/'embeddings_data.js')
print(json.dumps({'report':str(OUT/'index.html'),'headline':headline,'n':len(rows),'new_payload_contains_source_text':False}))
